// CSD_RATIONALE_BEGIN
// gsm_symbolic asks for chain-of-thought followed by a final answer wrapped
// in <<...>>. The verification surface has no parser, so constrained decoding
// is not load-bearing here; the evaluator scores the bracketed final expression.
// Empirically, the simplest unconstrained-per-token loop with brief guidance
// has dominated more elaborate variants. The previous attempt regressed by
// stacking many prohibitive rules; this revision keeps the proven loop and
// guidance shape, and only tightens two specific points that match the
// dominant failure mode (mode_E):
//   1) An explicit final-line template "The answer is <<EXPR>>" to discourage
//      multiple intermediate <<...>> spans (which confuse last-span extraction
//      and frequently still contain {brace} variables).
//   2) A single integer-division hint nudging // over / for whole-number ops.
// No structural change vs the best attempt; verification surface unchanged.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   insideConstrainedOut is initialized to false and never reassigned;
//   currentConstrainedOut stays []. The implication
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   is therefore vacuously preserved across every iteration.
// progress:
//   AppendTaskGuidance costs 0 and does not change generated. Each loop
//   iteration calls UnconstrainedStep, which consumes exactly one token-step;
//   we increment `steps` and `cost` by 1. On EOS we break without growing
//   `generated`; otherwise we append exactly one token. Thus
//   |generated| <= |generatedPrefix| + steps is preserved, and
//   cost == steps <= maxSteps. When maxSteps > 0 the loop runs at least
//   once, giving cost > 0 to satisfy the change disjunction.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := false;
currentConstrainedOut := [];
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve the math word problem step by step with concise arithmetic. End with exactly one line of the form: The answer is <<EXPR>>. EXPR is a single Python expression using only the variable names from the problem (no curly braces, no units). Use // for integer division of whole-number quantities.");

var steps := 0;
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant cost == steps
  invariant cost <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant |generated| <= |generatedPrefix| + steps
  invariant !insideConstrainedOut
  invariant currentConstrainedOut == []
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  cost := cost + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
}

